package com.eduflow.controller;
import com.eduflow.dto.AcademicDtos.*; import com.eduflow.entity.*; import com.eduflow.security.*; import com.eduflow.service.AcademicService; import com.eduflow.service.AuditLogService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1") @RequiredArgsConstructor @PreAuthorize("hasRole('USER')")
public class AcademicController {
 private final AcademicService service; private final CenterMembershipService memberships; private final AuditLogService audit;
 private Long center(AuthenticatedUser p){Long id=CurrentCenterContext.get();if(id==null)throw new com.eduflow.exception.EduFlowException(HttpStatus.BAD_REQUEST,"tenant.context.required");memberships.assertRoleForUserId(p.id(),id,Role.CENTER_ADMIN,Role.TEACHER);return id;}
 private void admin(AuthenticatedUser p,Long id){memberships.assertRoleForUserId(p.id(),id,Role.CENTER_ADMIN);}
 private ItemResponse teacher(Teacher x){return new ItemResponse(x.getId(),x.getTeacherCode(),x.getFirstName()+" "+x.getLastName(),x.getStatus(),x.getCreatedAt());}
 private ItemResponse course(Course x){return new ItemResponse(x.getId(),x.getCourseCode(),x.getName(),x.isActive()?"ACTIVE":"INACTIVE",x.getCreatedAt());}
 private ItemResponse group(StudyGroup x){return new ItemResponse(x.getId(),x.getGroupCode(),x.getName(),x.isActive()?"ACTIVE":"INACTIVE",x.getCreatedAt());}
 @GetMapping("/teachers") public List<ItemResponse> teachers(@AuthenticationPrincipal AuthenticatedUser p){return service.teachers(center(p)).stream().map(this::teacher).toList();}
 @PostMapping("/teachers") public ResponseEntity<ItemResponse> addTeacher(@AuthenticationPrincipal AuthenticatedUser p,@Valid @RequestBody TeacherRequest r){Long c=center(p);admin(p,c);Teacher x=service.addTeacher(c,r);audit.record(c,p.id(),"TEACHER_CREATED","Teacher",x.getId(),x.getTeacherCode());return ResponseEntity.status(201).body(teacher(x));}
 @GetMapping("/courses") public List<ItemResponse> courses(@AuthenticationPrincipal AuthenticatedUser p){return service.courses(center(p)).stream().map(this::course).toList();}
 @PostMapping("/courses") public ResponseEntity<ItemResponse> addCourse(@AuthenticationPrincipal AuthenticatedUser p,@Valid @RequestBody CourseRequest r){Long c=center(p);admin(p,c);Course x=service.addCourse(c,r);audit.record(c,p.id(),"COURSE_CREATED","Course",x.getId(),x.getCourseCode());return ResponseEntity.status(201).body(course(x));}
 @GetMapping("/groups") public List<ItemResponse> groups(@AuthenticationPrincipal AuthenticatedUser p){return service.groups(center(p)).stream().map(this::group).toList();}
 @PostMapping("/groups") public ResponseEntity<ItemResponse> addGroup(@AuthenticationPrincipal AuthenticatedUser p,@Valid @RequestBody GroupRequest r){Long c=center(p);admin(p,c);StudyGroup x=service.addGroup(c,r);audit.record(c,p.id(),"GROUP_CREATED","StudyGroup",x.getId(),x.getGroupCode());return ResponseEntity.status(201).body(group(x));}
 @PostMapping("/group-enrollments") public ResponseEntity<EnrollmentResponse> enroll(@AuthenticationPrincipal AuthenticatedUser p,@Valid @RequestBody EnrollmentRequest r){Long c=center(p);admin(p,c);GroupEnrollment x=service.enrollStudent(c,r.groupId(),r.studentId());audit.record(c,p.id(),"STUDENT_ENROLLED","GroupEnrollment",x.getId(),"Student "+r.studentId()+" enrolled in group "+r.groupId());return ResponseEntity.status(201).body(enrollment(x));}
 @GetMapping("/group-enrollments") public List<EnrollmentResponse> enrollments(@AuthenticationPrincipal AuthenticatedUser p,@RequestParam Long groupId){return service.groupEnrollments(center(p),groupId).stream().map(this::enrollment).toList();}
 @GetMapping("/groups/{groupId}/students") public List<EnrollmentResponse> groupStudents(@AuthenticationPrincipal AuthenticatedUser p,@PathVariable Long groupId){return service.groupEnrollments(center(p),groupId).stream().map(this::enrollment).toList();}
 private EnrollmentResponse enrollment(GroupEnrollment x){Student s=x.getStudent();return new EnrollmentResponse(x.getId(),x.getGroup().getId(),s.getId(),s.getStudentNumber(),s.getFirstName(),s.getLastName());}
 @GetMapping("/groups/{groupId}/lessons") public List<LessonResponse> lessons(@AuthenticationPrincipal AuthenticatedUser p,@PathVariable Long groupId){return service.lessons(center(p),groupId).stream().map(x->new LessonResponse(x.getId(),x.getGroup().getId(),x.getTitle(),x.getStartsAt(),x.getEndsAt(),x.getStatus())).toList();}
 @PostMapping("/lessons") public ResponseEntity<LessonResponse> addLesson(@AuthenticationPrincipal AuthenticatedUser p,@Valid @RequestBody LessonRequest r){Long c=center(p);Lesson x=service.addLesson(c,r);audit.record(c,p.id(),"LESSON_CREATED","Lesson",x.getId(),x.getTitle());return ResponseEntity.status(201).body(new LessonResponse(x.getId(),x.getGroup().getId(),x.getTitle(),x.getStartsAt(),x.getEndsAt(),x.getStatus()));}
 @PostMapping("/attendance") public ResponseEntity<AttendanceResponse> mark(@AuthenticationPrincipal AuthenticatedUser p,@Valid @RequestBody AttendanceRequest r){Long c=center(p);AttendanceRecord x=service.markAttendance(c,r);audit.record(c,p.id(),"ATTENDANCE_MARKED","AttendanceRecord",x.getId(),x.getStatus());return ResponseEntity.status(201).body(new AttendanceResponse(x.getId(),x.getLesson().getId(),x.getStudent().getId(),x.getStatus(),x.getNote()));}
 @GetMapping("/lessons/{lessonId}/attendance") public List<AttendanceResponse> attendance(@AuthenticationPrincipal AuthenticatedUser p,@PathVariable Long lessonId){return service.attendance(center(p),lessonId).stream().map(x->new AttendanceResponse(x.getId(),x.getLesson().getId(),x.getStudent().getId(),x.getStatus(),x.getNote())).toList();}
 @PostMapping("/grades") public ResponseEntity<GradeResponse> grade(@AuthenticationPrincipal AuthenticatedUser p,@Valid @RequestBody GradeRequest r){Long c=center(p);GradeRecord x=service.addGrade(c,r);audit.record(c,p.id(),"GRADE_CREATED","GradeRecord",x.getId(),x.getTitle()+":"+x.getScore()+"/"+x.getMaxScore());return ResponseEntity.status(201).body(new GradeResponse(x.getId(),x.getStudent().getId(),x.getGroup().getId(),x.getTitle(),x.getScore(),x.getMaxScore(),x.getComment(),x.getCreatedAt()));}
 @GetMapping("/students/{studentId}/grades") public List<GradeResponse> grades(@AuthenticationPrincipal AuthenticatedUser p,@PathVariable Long studentId){return service.grades(center(p),studentId).stream().map(x->new GradeResponse(x.getId(),x.getStudent().getId(),x.getGroup().getId(),x.getTitle(),x.getScore(),x.getMaxScore(),x.getComment(),x.getCreatedAt())).toList();}
}
